  "uzbek_hip_hop": {"parent":"mcRhythm.intlHipHop","axes":{"harm":0,"pitch":-1,"ornament":-1,"meter":1,"density":-1,"transmission":1,"improv":-1,"soundTech":2,"intensity":0,"voice":2,"timbre":0,"percussion":2,"cyclicity":2},"description":"Text-led rap and pitched refrains alternate over programmed backing. Electronic percussion and repeating melodic or bass figures support the vocal without imposing a fixed instrumental ensemble.","exemplars":["Shohrux"],"status":"documented","crossRefs":[]},
