  "depressive_black_metal": {"parent":"distortedRock.metal.black","axes":{"harm":0,"pitch":-1,"ornament":0,"meter":0,"density":1,"transmission":-1,"improv":0,"soundTech":1,"intensity":1,"voice":1,"timbre":2,"percussion":1,"cyclicity":2},"description":"Repeated melodic guitar layers, bass, expressive drumming and vocals unfold over long spans. Quieter keyboard space can contrast with dense passages; the category does not prescribe a diagnosis or one lyrical subject.","exemplars":["Austere — Corrosion of Hearts"],"status":"documented","crossRefs":[]},
  "downtempo_deathcore": {"parent":"distortedRock.metal.death","axes":{"harm":-1,"pitch":-2,"ornament":0,"meter":1,"density":1,"transmission":-1,"improv":0,"soundTech":2,"intensity":2,"voice":1,"timbre":2,"percussion":2,"cyclicity":2},"description":"Low clipped guitar and bass attacks align with widely spaced drum accents beneath harsh vocals. Silence and sustained decay between attacks contribute to weight without requiring every passage to remain slow.","exemplars":["Bound in Fear"],"status":"documented","crossRefs":[]},
