  "emotional_black_metal": {"parent":"distortedRock.metal.black","axes":{"harm":1,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":-1,"improv":0,"soundTech":1,"intensity":2,"voice":1,"timbre":2,"percussion":1,"cyclicity":2},"description":"Repeated melodic guitar textures and harsh vocals meet bass and drums, with quieter spaces and keyboard or sampled layers. Atmospheric and depressive approaches overlap without making one subject or mood compulsory.","exemplars":["Waldgeflüster — Dahoam"],"status":"documented","crossRefs":[]},
