  "metal_tico": {"parent":"distortedRock.metal","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":-1,"improv":0,"soundTech":1,"intensity":2,"voice":1,"timbre":1,"percussion":1,"cyclicity":0},"description":"Weighty power chords and answering leads sit over a steady bass-and-drum foundation with sung lead lines. Clear spaces between accents distinguish the traditional heavy branch from denser extreme styles.","exemplars":["Thunderborne — Out of Order"],"status":"documented","crossRefs":[]},
  "metal_noir_quebecois": {"parent":"distortedRock.metal.black","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":-1,"improv":0,"soundTech":1,"intensity":2,"voice":1,"timbre":1,"percussion":1,"cyclicity":0},"description":"Layered tremolo guitars, bass and alternating spacious and rapid drums support exposed harsh vocals. Long transitions vary the texture; winter imagery is one recurring strand rather than a mandatory theme.","exemplars":["Janvier — L’Hiver n’est jamais fini"],"status":"documented","crossRefs":[]},
