  "lithuanian_metal": {"parent":"distortedRock.metal","axes":{"harm":-1,"pitch":-1,"ornament":1,"meter":1,"density":2,"transmission":0,"improv":0,"soundTech":1,"intensity":2,"voice":1,"timbre":2,"percussion":2,"cyclicity":0},"description":"Repeated guitar motion and broad changes in density frame bass, drums and vocals. Layered riffs can expand into sustained textures before returning to heavier rhythmic passages.","exemplars":["Au-Dessus"],"status":"documented","crossRefs":[]},
