  "metal_colombiano": {"parent":"distortedRock.metal","axes":{"harm":1,"pitch":1,"ornament":1,"meter":1,"density":1,"transmission":0,"improv":0,"soundTech":1,"intensity":2,"voice":2,"timbre":1,"percussion":2,"cyclicity":2},"description":"Prominent sung melodies and guitar leads sit over power chords, bass and drums. Keyboards can add themes and harmonic support within the hard-rock and melodic-metal branches.","exemplars":["Kraken"],"status":"documented","crossRefs":[]},
  "metal_cover": {"parent":"distortedRock.metal","axes":{"harm":1,"pitch":0,"ornament":1,"meter":1,"density":2,"transmission":0,"improv":0,"soundTech":1,"intensity":2,"voice":2,"timbre":1,"percussion":2,"cyclicity":2},"description":"Recognizable vocal melodies are recast against distorted guitar riffs, electric bass and forceful drums. Frog Leap exemplifies the practice of carrying pop hooks into an amplified live-band setting.","exemplars":["Frog Leap"],"status":"documented","crossRefs":[]},
