  "polish_folk_metal": {"parent":"distortedRock.metal.folkMetal","axes":{"harm":0,"pitch":0,"ornament":1,"meter":1,"density":1,"transmission":0,"improv":-1,"soundTech":2,"intensity":1,"voice":1,"timbre":1,"percussion":1,"cyclicity":1},"description":"Heavy electric riffs, bass and drums can support prominent cello melodies and interwoven voices. Percival Schuttenbach exemplifies this amplified treatment of Polish and neighbouring regional repertoire.","exemplars":["Percival Schuttenbach — Reakcja pogańska"],"status":"documented","crossRefs":[]},
