  "icelandic_jazz": {"parent":"improvOnFrame.americanJazz","axes":{"harm":2,"pitch":1,"ornament":1,"meter":0,"density":-1,"transmission":1,"improv":2,"soundTech":-1,"intensity":-1,"voice":-2,"timbre":0,"percussion":1,"cyclicity":0},"description":"Piano, double bass and drums can shape spacious melodic arrangements through close listening and responsive accompaniment. Composed themes open into improvised development, with contrasts in touch and density.","exemplars":["Sunna Gunnlaugs Trio"],"status":"documented","crossRefs":[]},
  "indonesian_jazz": {"parent":"improvOnFrame.americanJazz","axes":{"harm":2,"pitch":1,"ornament":2,"meter":0,"density":1,"transmission":1,"improv":2,"soundTech":-1,"intensity":1,"voice":-2,"timbre":0,"percussion":1,"cyclicity":0},"description":"A piano trio brings melodic improvisation and harmonic variation into dialogue with double bass and drums. Rhythmic detail and responsive accompaniment allow composed themes to develop through ensemble exchange.","exemplars":["Joey Alexander Trio"],"status":"documented","crossRefs":[]},
  "jazz_boom_bap": {"parent":"mcRhythm.usHipHop","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":0,"soundTech":2,"intensity":0,"voice":-2,"timbre":1,"percussion":2,"cyclicity":2},"description":"Chopped record samples and drum breaks build repeating grooves with layered melodic fragments. Changes in sample placement and texture give the beat movement while preserving its rhythmic foundation.","exemplars":["Damu The Fudgemunk"],"status":"documented","crossRefs":[]},
  "jazz_caraibes": {"parent":"improvOnFrame.latinJazz","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":1,"soundTech":0,"intensity":0,"voice":1,"timbre":1,"percussion":-1,"cyclicity":0},"description":"Piano and voice provide one intimate setting for Caribbean melodic material and jazz development. Flexible keyboard accompaniment and vocal phrasing coexist with more rhythm-section-led and instrumental approaches across the field.","exemplars":["Grégory Privat"],"status":"documented","crossRefs":[]},
  "jazz_cover": {"parent":"improvOnFrame.americanJazz","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":1,"soundTech":0,"intensity":0,"voice":-2,"timbre":1,"percussion":-1,"cyclicity":0},"description":"Solo piano can reshape a melody through altered accompaniment, harmonic movement and improvised development. Vocal groups and larger instrumental ensembles offer other ways to recast popular repertoire.","exemplars":["Brad Mehldau"],"status":"documented","crossRefs":[]},
