  "jazz_flute": {"parent":"improvOnFrame.americanJazz","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":2,"soundTech":0,"intensity":0,"voice":-2,"timbre":1,"percussion":1,"cyclicity":0},"description":"Flute lines can unfold over piano, plucked bass and drums, combining melodic detail with responsive rhythmic support. Vocals, hand percussion and other instruments may join in wider arrangements.","exemplars":["Nicole Mitchell"],"status":"documented","crossRefs":[]},
