  "modern_free_jazz": {"parent":"improvOnFrame.americanJazz.avant","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":2,"soundTech":0,"intensity":-1,"voice":-2,"timbre":0,"percussion":0,"cyclicity":0},"description":"Piano, double bass and drums can exchange short ideas, leave space or build denser passages together. Responsive phrasing and flexible rhythmic organization matter more than a constant backing pattern.","exemplars":["Matthew Shipp Trio"],"status":"documented","crossRefs":[]},
