  "lithuanian_jazz": {"parent":"improvOnFrame.americanJazz","axes":{"harm":1,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":0,"improv":2,"soundTech":1,"intensity":1,"voice":-2,"timbre":0,"percussion":1,"cyclicity":0},"description":"A saxophone, electric guitar and drum trio offers one open-textured branch. Contrasting instrumental gestures and rhythmic exchanges can move between written ideas and freer development without a fixed bass role.","exemplars":["Sheep Got Waxed"],"status":"documented","crossRefs":[]},
  "russian_modern_jazz": {"parent":"improvOnFrame.americanJazz","axes":{"harm":1,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":0,"improv":1,"soundTech":0,"intensity":0,"voice":-2,"timbre":0,"percussion":0,"cyclicity":0},"description":"Piano, double bass and drums can combine melodic writing with responsive improvisation. Contrasting rhythmic patterns and harmonic colours shape the interaction; guest voices, strings or pedal steel may expand particular arrangements.","exemplars":["LRK Trio with Bosse Savik"],"status":"documented","crossRefs":[]},
  "psychedelic_jazz_fusion": {"parent":"improvOnFrame.americanJazz.fusion","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":0,"improv":2,"soundTech":1,"intensity":2,"voice":-2,"timbre":0,"percussion":1,"cyclicity":0},"description":"Electric guitar, bass and drums can interact with a freely phrased saxophone lead. Fuzz-rich riffs, changing density and collective development connect rock weight with open-ended instrumental exchange.","exemplars":["Black Bombaim & Peter Brötzmann"],"status":"documented","crossRefs":[]},
  "russian_jazz": {"parent":"improvOnFrame.americanJazz","axes":{"harm":1,"pitch":0,"ornament":0,"meter":0,"density":1,"transmission":0,"improv":2,"soundTech":0,"intensity":0,"voice":-2,"timbre":0,"percussion":1,"cyclicity":0},"description":"Trumpet and tenor saxophone can share the melodic foreground over piano, double bass and drums. Written themes, harmonic development and responsive solo accompaniment shape a representative quintet arrangement.","exemplars":["Alex Sipiagin"],"status":"documented","crossRefs":[]},
