  "classical_guitar": {"parent":"artMusic.westernEarly","axes":{"harm":1,"pitch":1,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":-1,"soundTech":0,"intensity":0,"voice":-2,"timbre":1,"percussion":-1,"cyclicity":0},"description":"Fingerpicked nylon strings support independent lines, chords and resonant bass notes. Touch and articulation shape contrasts in tone and rhythm, while solo, chamber and concerto settings offer different scales of musical development.","exemplars":["Sean Shibe"],"status":"documented","crossRefs":[]},
  "classical_guitar_duo": {"parent":"artMusic.westernCommonPractice","axes":{"harm":1,"pitch":1,"ornament":0,"meter":0,"density":1,"transmission":0,"improv":-1,"soundTech":0,"intensity":0,"voice":-2,"timbre":1,"percussion":-1,"cyclicity":0},"description":"Interlocking plucked lines can alternate with shared chords and contrasting registers. Coordinated articulation and dynamic balance keep the parts distinct while allowing the two guitars to form a unified texture.","exemplars":["Katona Twins"],"status":"documented","crossRefs":[]},
