  "classical_harp": {"parent":"artMusic","axes":{"harm":1,"pitch":1,"ornament":0,"meter":0,"density":0,"transmission":0,"improv":-1,"soundTech":0,"intensity":0,"voice":-2,"timbre":1,"percussion":-1,"cyclicity":0},"description":"Plucked strings can carry sustained harmonies, articulated figures and contrasting registers. Pedal changes and careful damping shape harmonic movement and clarity, with solo and ensemble settings using different balances of resonance.","exemplars":["Susan Drake"],"status":"documented","crossRefs":[]},
  "classical_piano": {"parent":"artMusic.westernCommonPractice","axes":{"harm":2,"pitch":0,"ornament":1,"meter":0,"density":-1,"transmission":2,"improv":-2,"soundTech":-1,"intensity":0,"voice":-2,"timbre":0,"percussion":-2,"cyclicity":0},"description":"One piano can combine melody, bass and inner voices, with touch and pedal shaping articulation and resonance. Contrasts in register, density and dynamic weight organize both short pieces and larger musical forms.","exemplars":["Víkingur Ólafsson"],"status":"documented","crossRefs":[]},
